/// <summary>
/// Picks up the key-pickup <see cref="WorldItem"/> the player is aiming at when the pickup key is
/// pressed: grants its item(s) to the inventory and removes it from the world. Only non-auto-collect
/// items (e.g. the wrench) need this — auto-collect drops fly to the player on their own.
/// Reads the hovered item from <see cref="PlayerMouseAimer"/>; writes to <see cref="PlayerInventory"/>.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerPickupController : MonoBehaviour
{
    [SerializeField] private KeyCode _pickupKey = KeyCode.E;

    private PlayerMouseAimer _aimer;
    private PlayerCarryController _carry;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _carry = GetComponent<PlayerCarryController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_pickupKey)) return;

        // Skip pickup while carrying an object
        if (_carry != null && _carry.IsCarrying) return;

        WorldItem item = _aimer.HoveredKeyPickup;
        if (item == null || item.Item == null) return;

        PlayerInventory inv = PlayerInventory.Instance;
        if (inv == null) return;

        int added = inv.TryAddItem(item.Item, item.Count);
        if (added <= 0) return;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemPickedUp(item.Item, added));

        if (added >= item.Count) Destroy(item.gameObject);
        else                     item.Reduce(added);
    }
}

using System;
using UnityEngine;

/// <summary>
/// Owns the runtime inventory state (copied from <see cref="InventoryData"/> on Awake — the SO
/// itself is never mutated at runtime). Holds a flat array of <see cref="InventorySlot"/>s:
/// slot 0 is the wrench slot, slots 1..N are general item slots that stack identical items up to
/// <see cref="ItemDefinition.maxStack"/>. The slot count is data-driven and extendable.
///
/// Accepts any item kind (resources, future tools, etc.). Currency items never enter a slot —
/// they route to their <see cref="ItemDefinition.currencyTarget"/> at the collection site.
/// Handles hotkey input (1-4) to switch the active slot; raises events for the HUD.
///
/// Acts as the game's inventory manager: a singleton (<see cref="Instance"/>) so the HUD, pickup,
/// drop, magnets and the wrench controllers all reach inventory through one access point and
/// subscribe to its events — no FindObjectOfType, no per-system GetComponent. Single-player, so one
/// instance is assumed. Runs early (negative execution order) so <see cref="Instance"/> exists
/// before any subscriber's Awake/OnEnable.
///
/// Pure manager — holds no scene-position state and never touches the character controller, so it
/// lives on a dedicated manager GameObject (e.g. MANAGERS/INVENTORY), not on the Player. All users
/// reach it through <see cref="Instance"/>; nothing requires it to share the Player's GameObject.
/// </summary>
[DefaultExecutionOrder(-50)]
public class PlayerInventory : MonoBehaviour
{
    /// <summary>The active inventory manager. Set in Awake, cleared on destroy.</summary>
    public static PlayerInventory Instance { get; private set; }

    public const int WrenchSlot = 0;

    [SerializeField] private InventoryData _inventoryConfig;

    public event Action<int> OnSlotChanged;
    public event Action<int> OnActiveSlotChanged;

    private InventorySlot[] _runtimeSlots = Array.Empty<InventorySlot>();
    private int _activeSlot;

    // ── Public API ────────────────────────────────────────────────────────────

    public int SlotCount => _runtimeSlots.Length;

    public int ActiveSlotIndex
    {
        get => _activeSlot;
        private set
        {
            int clamped = Mathf.Clamp(value, 0, SlotCount - 1);
            if (_activeSlot == clamped) return;
            _activeSlot = clamped;
            OnActiveSlotChanged?.Invoke(_activeSlot);
        }
    }

    public InventorySlot ActiveSlot => GetSlot(_activeSlot);
    public ItemDefinition ActiveItem => ActiveSlot.item;

    /// <summary>ItemType of the currently selected slot, or None if it's empty.</summary>
    public ItemType ActiveItemType => ActiveItem != null ? ActiveItem.itemType : ItemType.None;

    /// <summary>True when no general slot is empty (can't accept a new item kind).</summary>
    public bool IsFull
    {
        get
        {
            for (int i = 1; i < _runtimeSlots.Length; i++)
                if (_runtimeSlots[i].IsEmpty) return false;
            return true;
        }
    }

    public InventorySlot GetSlot(int index)
    {
        if (index < 0 || index >= _runtimeSlots.Length) return InventorySlot.Empty;
        return _runtimeSlots[index];
    }

    /// <summary>True if any slot currently holds an item of the given type.</summary>
    public bool HasItem(ItemType type)
    {
        for (int i = 0; i < _runtimeSlots.Length; i++)
            if (!_runtimeSlots[i].IsEmpty && _runtimeSlots[i].item.itemType == type) return true;
        return false;
    }

    /// <summary>
    /// True if at least one unit of <paramref name="item"/> can be accepted right now
    /// (a matching non-full stack, or an empty slot). Used by world-item magnets to decide
    /// whether to fly to the player or stay on the ground.
    /// </summary>
    public bool HasRoomFor(ItemDefinition item)
    {
        if (item == null || item.isCurrency) return false;

        if (item.itemType == ItemType.Wrench)
            return GetSlot(WrenchSlot).IsEmpty;

        for (int i = 1; i < _runtimeSlots.Length; i++)
        {
            if (_runtimeSlots[i].IsEmpty) return true;
            if (_runtimeSlots[i].item == item && !_runtimeSlots[i].IsFull) return true;
        }
        return false;
    }

    /// <summary>
    /// Add up to <paramref name="count"/> of <paramref name="item"/>, stacking into matching
    /// slots first then filling empty ones. Returns how many were actually added (0 = no room).
    /// Currency items are rejected here (they belong on the currency counter, not a slot).
    /// </summary>
    public int TryAddItem(ItemDefinition item, int count = 1)
    {
        if (item == null || count <= 0 || item.isCurrency) return 0;

        if (item.itemType == ItemType.Wrench)
        {
            if (!GetSlot(WrenchSlot).IsEmpty) return 0;
            _runtimeSlots[WrenchSlot] = InventorySlot.Of(item, 1);
            OnSlotChanged?.Invoke(WrenchSlot);
            return 1;
        }

        int added = 0;

        // 1) Top up existing matching stacks.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (_runtimeSlots[i].item != item || _runtimeSlots[i].IsFull) continue;
            int take = Mathf.Min(_runtimeSlots[i].SpaceLeft, count - added);
            _runtimeSlots[i].count += take;
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        // 2) Fill empty slots.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (!_runtimeSlots[i].IsEmpty) continue;
            int take = Mathf.Min(Mathf.Max(1, item.maxStack), count - added);
            _runtimeSlots[i] = InventorySlot.Of(item, take);
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        return added;
    }

    /// <summary>Remove one unit from a slot; returns the item removed, or null if the slot was empty.</summary>
    public ItemDefinition RemoveOne(int index) => RemoveFromSlot(index, 1, out _);

    /// <summary>Remove the whole stack from a slot; returns the item and (via out) how many were removed.</summary>
    public ItemDefinition RemoveStack(int index, out int removed)
        => RemoveFromSlot(index, int.MaxValue, out removed);

    /// <summary>Remove up to <paramref name="count"/> units from a slot.</summary>
    public ItemDefinition RemoveFromSlot(int index, int count, out int removed)
    {
        removed = 0;
        if (index < 0 || index >= _runtimeSlots.Length || count <= 0) return null;

        InventorySlot slot = _runtimeSlots[index];
        if (slot.IsEmpty) return null;

        ItemDefinition item = slot.item;
        removed = Mathf.Min(count, slot.count);
        slot.count -= removed;
        _runtimeSlots[index] = slot.count <= 0 ? InventorySlot.Empty : slot;
        OnSlotChanged?.Invoke(index);
        return item;
    }

    // ── Signals (inbound) ───────────────────────────────────────────────────────
    // Readability aliases over the API above. Same pattern as ResourceManager.RaiseHit:
    // a gameplay system "signals" the inventory (e.g. a pickup collision), the inventory
    // mutates its slots, then broadcasts OnSlotChanged / OnActiveSlotChanged outward.
    // The store is the one place that owns slot state — these just read like events.

    /// <summary>Signal: an item pickup was requested (e.g. by a collision/magnet). Returns how
    /// many units actually entered the inventory. Forwards to <see cref="TryAddItem"/>.</summary>
    public int SignalPickup(ItemDefinition item, int count = 1) => TryAddItem(item, count);

    /// <summary>Signal: drop one unit from a slot. Returns the item removed, or null if empty.
    /// Forwards to <see cref="RemoveOne"/>.</summary>
    public ItemDefinition SignalDropOne(int slot) => RemoveOne(slot);

    /// <summary>Signal: drop a whole stack from a slot. Forwards to <see cref="RemoveStack"/>.</summary>
    public ItemDefinition SignalDropStack(int slot, out int removed) => RemoveStack(slot, out removed);

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
            Debug.LogWarning($"[PlayerInventory] Second instance on '{name}'; overriding the previous Instance.", this);
        Instance = this;

        int count = _inventoryConfig != null ? _inventoryConfig.Slots : 4;
        _runtimeSlots = new InventorySlot[count];
        for (int i = 0; i < count; i++)
        {
            ItemDefinition def = _inventoryConfig != null ? _inventoryConfig.GetDefaultSlot(i) : null;
            _runtimeSlots[i] = def != null ? InventorySlot.Of(def, 1) : InventorySlot.Empty;
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        ReadHotkeys();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void ReadHotkeys()
    {
        if (Input.GetKeyDown(KeyCode.Alpha1))      ActiveSlotIndex = 0;
        else if (Input.GetKeyDown(KeyCode.Alpha2)) ActiveSlotIndex = 1;
        else if (Input.GetKeyDown(KeyCode.Alpha3)) ActiveSlotIndex = 2;
        else if (Input.GetKeyDown(KeyCode.Alpha4)) ActiveSlotIndex = 3;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemDropped(item, count, pos));
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Drives the <see cref="InteractTagPanel"/> from the hover source. Reads
/// <see cref="PlayerMouseAimer.HoverResult"/> each frame and positions the
/// panel at the interactable's world anchor with its prompt text. When nothing is
/// hovered the tag is hidden. Also supports scan progress prompts.
///
/// Subscribes to <see cref="ScanProgressed"/> events from the GameEventBus to
/// show scan progress feedback when scanning an artifact.
/// </summary>
public class WorldInteractTagPresenter : MonoBehaviour
{
    [SerializeField] private PlayerMouseAimer _aimer;
    [SerializeField] private InteractTagPanel _tagPanel;

    private ScanTarget _activeScanTarget;
    private float _lastScanProgress;

    private void Awake()
    {
        if (_aimer == null) _aimer = FindObjectOfType<PlayerMouseAimer>();
        if (_tagPanel == null) _tagPanel = FindObjectOfType<InteractTagPanel>();
    }

    private void OnEnable()
    {
        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Subscribe<ScanProgressed>(OnScanProgressed);
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Unsubscribe<ScanProgressed>(OnScanProgressed);
        _activeScanTarget = null;
    }

    private void LateUpdate()
    {
        if (_aimer == null || _tagPanel == null) return;

        // Check for active scan progress first (overrides normal prompt)
        if (_activeScanTarget != null && _lastScanProgress > 0f && _lastScanProgress < 1f)
        {
            int pct = Mathf.RoundToInt(_lastScanProgress * 100);
            _tagPanel.Show($"[F]  Scanning... {pct}%");
            return;
        }

        // Read from the unified hover result
        var result = _aimer.HoverResult;
        IInteractionPromptProvider hovered = result.Interactable;

        // Interface refs to destroyed Unity objects bypass the fake-null check.
        if (hovered is UnityEngine.Object obj && obj == null) hovered = null;

        if (hovered != null && hovered.TryGetPrompt(out InteractionPrompt prompt) && prompt.IsValid)
        {
            _tagPanel.Show(prompt.Display);
        }
        else
        {
            _tagPanel.HideTag();
        }
    }

    private void OnScanProgressed(ScanProgressed evt)
    {
        if (evt.Target == null) return;
        _activeScanTarget = evt.Target;
        _lastScanProgress = evt.Percent;
    }
}

using UnityEngine;

/// <summary>
/// Basic 2D character controller for pure XY-plane movement.
/// Uses Rigidbody2D for collision-aware movement.
/// Reads legacy Input manager axes (Horizontal, Vertical).
/// Responds to terrain zones via <see cref="TerrainStateAggregator2D"/>.
/// </summary>
[DefaultExecutionOrder(-50)]
[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(SpriteRenderer))]
[RequireComponent(typeof(TerrainStateAggregator2D))]
public class PlayerController2D : MonoBehaviour
{
    [Header("Movement")]
    [Tooltip("Maximum movement speed in units/sec.")]
    [SerializeField] private float _moveSpeed = 5f;

    [Tooltip("How quickly the character accelerates to max speed.")]
    [SerializeField] private float _acceleration = 12f;

    [Tooltip("How quickly the character decelerates to zero.")]
    [SerializeField] private float _deceleration = 10f;

    [Header("Facing")]
    [Tooltip("Flip the sprite to face movement direction.")]
    [SerializeField] private bool _flipToFaceDirection = true;

    // ── Components ────────────────────────────────────────────────────────

    private Rigidbody2D _rb;
    private SpriteRenderer _sr;
    private TerrainStateAggregator2D _terrain;

    // ── Public State ──────────────────────────────────────────────────────

    public Vector2 MoveInput { get; private set; }
    public Vector2 Velocity => _rb.velocity;
    public float NormalizedSpeed => _moveSpeed > 0f ? _rb.velocity.magnitude / _moveSpeed : 0f;
    public bool IsMoving => MoveInput.sqrMagnitude > 0.01f;
    public bool CanJump => _terrain != null && !_terrain.CurrentState.BlocksJump;

    // ── Lifecycle ──────────────────────────────────────────────────────────

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _sr = GetComponent<SpriteRenderer>();
        _terrain = GetComponent<TerrainStateAggregator2D>();

        _rb.gravityScale = 0f;
        _rb.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
        _rb.freezeRotation = true;
        _rb.interpolation = RigidbodyInterpolation2D.Interpolate;
    }

    private void Update()
    {
        MoveInput = new Vector2(Input.GetAxisRaw("Horizontal"), Input.GetAxisRaw("Vertical"));
        if (MoveInput.sqrMagnitude > 1f)
            MoveInput.Normalize();
    }

    private void FixedUpdate()
    {
        var terrain = _terrain.CurrentState;

        // Terrain modifiers
        float speedMul = terrain.SpeedMultiplier;
        float decelRetention = terrain.DecelerationRetention;

        Vector2 targetVelocity = MoveInput * _moveSpeed * speedMul;
        float delta = Time.fixedDeltaTime;
        float accel = _acceleration;
        float decel = _deceleration * decelRetention;

        Vector2 velocity = _rb.velocity;

        if (MoveInput.sqrMagnitude > 0.01f)
        {
            // On ice: also reduce acceleration for slidey feel
            if (terrain.LowGrip) accel *= decelRetention;
            velocity = Vector2.MoveTowards(velocity, targetVelocity, accel * delta);
        }
        else
        {
            velocity = Vector2.MoveTowards(velocity, Vector2.zero, decel * delta);
        }

        // Apply external forces (wind, etc.)
        velocity += terrain.ExternalForce * delta;

        _rb.velocity = velocity;

        // Flip sprite to face movement direction
        if (_flipToFaceDirection && MoveInput.x != 0f)
            _sr.flipX = MoveInput.x < 0f;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central UI relay — same factory/hub pattern as ResourceManager and PlayerInventory: gameplay
/// systems fire an inbound signal (<see cref="SignalShow"/> / <see cref="SignalHide"/> /
/// <see cref="SignalToggle"/>), the manager routes it to the matching reusable panel, then
/// broadcasts an outbound event (<see cref="OnPanelShown"/> / <see cref="OnPanelHidden"/>).
///
/// Callers never reference a concrete screen — they only know a <see cref="UIPanelId"/> and reach
/// the manager through <see cref="Instance"/>. The manager owns the list of reusable panels and
/// reuses them (show/hide), never instantiating per request.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> and the registry
/// exist before any caller's Awake/OnEnable.
/// </summary>
[DefaultExecutionOrder(-100)]
public class UIManager : MonoBehaviour
{
    public static UIManager Instance { get; private set; }

    [Tooltip("Log each show/hide signal. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    [Tooltip("Reusable panels managed here. Drop UIPanel components in, or Register at runtime.")]
    [SerializeField] private List<UIPanel> _panels = new();

    private readonly Dictionary<UIPanelId, IUIPanel> _registry = new();

    /// <summary>Raised after a panel is shown. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelShown;
    /// <summary>Raised after a panel is hidden. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelHidden;

    // ── Signals (inbound) ───────────────────────────────────────────────────────

    /// <summary>Signal: show the panel with this id. No-op (warns) if none is registered.</summary>
    public void SignalShow(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] show {id}");
        panel.Show();
        OnPanelShown?.Invoke(id);
    }

    /// <summary>Signal: hide the panel with this id.</summary>
    public void SignalHide(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] hide {id}");
        panel.Hide();
        OnPanelHidden?.Invoke(id);
    }

    /// <summary>Signal: toggle the panel's visibility.</summary>
    public void SignalToggle(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (panel.IsVisible) SignalHide(id);
        else SignalShow(id);
    }

    public bool IsVisible(UIPanelId id) => TryGet(id, out IUIPanel p, warn: false) && p.IsVisible;

    // ── Registration ──────────────────────────────────────────────────────────

    /// <summary>Register a panel at runtime (panels in the serialized list register automatically).</summary>
    public void Register(IUIPanel panel)
    {
        if (panel == null || panel.PanelId == UIPanelId.None) return;
        _registry[panel.PanelId] = panel;
    }

    public void Unregister(IUIPanel panel)
    {
        if (panel == null) return;
        if (_registry.TryGetValue(panel.PanelId, out IUIPanel existing) && existing == panel)
            _registry.Remove(panel.PanelId);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[UIManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;

        foreach (UIPanel panel in _panels)
        {
            if (panel == null) continue;
            if (panel.PanelId == UIPanelId.None)
            {
                Debug.LogWarning($"[UIManager] '{panel.name}' has PanelId.None; skipped.", panel);
                continue;
            }
            Register(panel);
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private bool TryGet(UIPanelId id, out IUIPanel panel, bool warn = true)
    {
        if (_registry.TryGetValue(id, out panel) && panel != null) return true;
        if (warn) Debug.LogWarning($"[UIManager] No panel registered for {id}.", this);
        return false;
    }
}

using System;
using UnityEngine;

/// <summary>
/// Single source of truth for the mouse pointer. One per scene (lives on the UI manager object).
/// Every frame it reads the cursor, builds ONE world ray, and casts ONCE against a combined layer
/// mask — then caches the result. Gameplay and UI read these cached values instead of each running
/// their own <c>Camera.ScreenPointToRay(Input.mousePosition)</c> + <c>Physics.Raycast</c>.
///
/// Same hub idea as the other managers: record the signal once, everyone else just reads it. Runs
/// early (negative execution order) so the cache is fresh before any default-order consumer's Update.
/// </summary>
[DefaultExecutionOrder(-90)]
public class MousePointer : MonoBehaviour
{
    public static MousePointer Instance { get; private set; }

    [Tooltip("Camera the cursor ray is built from. Falls back to Camera.main.")]
    [SerializeField] private Camera _camera;
    [Tooltip("Combined mask for the per-frame world cast — the union of everything UI/gameplay needs.")]
    [SerializeField] private LayerMask _worldMask = ~0;
    [SerializeField] private float _maxDistance = 100f;

    // ── Cached each frame ───────────────────────────────────────────────────────

    /// <summary>Cursor position in screen pixels (== Input.mousePosition).</summary>
    public Vector2 ScreenPosition { get; private set; }
    /// <summary>Ray from the camera through the cursor.</summary>
    public Ray WorldRay { get; private set; }
    /// <summary>True if this frame's cast hit a collider on <see cref="_worldMask"/>.</summary>
    public bool HasHit { get; private set; }
    /// <summary>This frame's raycast hit (valid only when <see cref="HasHit"/>).</summary>
    public RaycastHit Hit { get; private set; }
    /// <summary>Hit point if we hit, else the ray projected to max distance (always usable as an aim target).</summary>
    public Vector3 WorldPoint { get; private set; }
    /// <summary>Collider under the cursor this frame, or null.</summary>
    public Collider HoverCollider { get; private set; }
    /// <summary>GameObject under the cursor this frame, or null.</summary>
    public GameObject HoverObject { get; private set; }

    /// <summary>Fires when the hovered GameObject changes (including to/from null).</summary>
    public event Action<GameObject> OnHoverChanged;

    private GameObject _lastHover;

    // ── Public helpers ──────────────────────────────────────────────────────────

    /// <summary>True when the current hover object sits on one of the given layers.</summary>
    public bool HoverOnLayers(LayerMask mask)
        => HoverObject != null && (mask.value & (1 << HoverObject.layer)) != 0;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[MousePointer] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        if (_camera == null) _camera = Camera.main;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_camera == null)
        {
            _camera = Camera.main;
            if (_camera == null) return;
        }

        ScreenPosition = Input.mousePosition;
        WorldRay = _camera.ScreenPointToRay(ScreenPosition);

        HasHit = Physics.Raycast(WorldRay, out RaycastHit hit, _maxDistance, _worldMask, QueryTriggerInteraction.Ignore);
        Hit = hit;

        if (HasHit)
        {
            WorldPoint = hit.point;
            HoverCollider = hit.collider;
            HoverObject = hit.collider != null ? hit.collider.gameObject : null;
        }
        else
        {
            WorldPoint = WorldRay.GetPoint(_maxDistance);
            HoverCollider = null;
            HoverObject = null;
        }

        if (HoverObject != _lastHover)
        {
            _lastHover = HoverObject;
            OnHoverChanged?.Invoke(HoverObject);
        }
    }
}
